insert into public.ranked_questions (id, destination, difficulty, question, options, correct_option_id, explanation, source_id) values
('moon-01','moon','beginner','What is the Moon?','[{"id":"a","text":"A star"},{"id":"b","text":"Earth’s natural satellite"},{"id":"c","text":"An artificial satellite"},{"id":"d","text":"A dwarf planet"}]'::jsonb,'b','The Moon is Earth’s only natural satellite — it was not built by people.','nasa-moon'),
('moon-02','moon','beginner','What mostly made the Moon’s craters?','[{"id":"a","text":"Ancient rivers"},{"id":"b","text":"Volcanic geysers only"},{"id":"c","text":"Impacts from asteroids and comets"},{"id":"d","text":"Rocket landings"}]'::jsonb,'c','Most lunar craters come from impacts of space rocks over billions of years.','nasa-moon'),
('moon-03','moon','beginner','About how strong is gravity on the Moon compared with Earth?','[{"id":"a","text":"About one-sixth"},{"id":"b","text":"About twice as strong"},{"id":"c","text":"Exactly the same"},{"id":"d","text":"Zero gravity"}]'::jsonb,'a','Lunar gravity is about 1/6 of Earth’s, so astronauts can bounce.','nasa-moon'),
('moon-04','moon','beginner','How many astronauts walked on the Moon during Apollo (1969–1972)?','[{"id":"a","text":"Two"},{"id":"b","text":"Six"},{"id":"c","text":"Twenty-four"},{"id":"d","text":"Twelve"}]'::jsonb,'d','Twelve Apollo astronauts walked on the lunar surface.','nasa-moon'),
('moon-05','moon','intermediate','Why do we always see the same side of the Moon from Earth?','[{"id":"a","text":"The Moon does not spin"},{"id":"b","text":"It is tidally locked: it spins once per orbit"},{"id":"c","text":"Earth blocks the other side"},{"id":"d","text":"The far side is always dark"}]'::jsonb,'b','Tidal locking means one rotation takes the same time as one orbit.','nasa-moon'),
('moon-06','moon','intermediate','Why can’t you breathe on the Moon without a suit?','[{"id":"a","text":"It is too windy"},{"id":"b","text":"The air is full of smoke"},{"id":"c","text":"It has almost no atmosphere"},{"id":"d","text":"Its air is pure nitrogen"}]'::jsonb,'c','The Moon has only an extremely thin exosphere — no breathable air.','nasa-moon'),
('moon-07','moon','intermediate','Roughly how far is the Moon from Earth on average?','[{"id":"a","text":"384,400 km"},{"id":"b","text":"3,844 km"},{"id":"c","text":"38.4 million km"},{"id":"d","text":"150 million km"}]'::jsonb,'a','The average Earth–Moon distance is about 384,400 km. (150 million km is Earth–Sun.)','nasa-moon'),
('moon-08','moon','intermediate','Which is true about the Moon and an artificial satellite?','[{"id":"a","text":"Both were built by people"},{"id":"b","text":"Neither orbits Earth"},{"id":"c","text":"The Moon is artificial"},{"id":"d","text":"Both orbit Earth, but only the satellite is human-made"}]'::jsonb,'d','Natural satellites form naturally; artificial satellites are human-made machines.','nasa-moon'),
('moon-09','moon','advanced','Mission decision: Your oxygen is at 20% and the relay is far away. What is the safest plan?','[{"id":"a","text":"Ignore oxygen and run to the relay"},{"id":"b","text":"Collect an oxygen canister or return to camp first"},{"id":"c","text":"Remove your helmet to save weight"},{"id":"d","text":"Wait for the Moon’s air to refill your tank"}]'::jsonb,'b','With no breathable air, astronauts must protect their oxygen supply before continuing.','nasa-moon'),
('moon-10','moon','advanced','Mission decision: Lunar dust is sharp and clingy. What should you do before re-entering the habitat?','[{"id":"a","text":"Brush and contain dust using the airlock procedure"},{"id":"b","text":"Shake your suit inside the habitat"},{"id":"c","text":"Wash it off with river water"},{"id":"d","text":"Nothing — Moon dust is harmless"}]'::jsonb,'a','Abrasive lunar regolith can damage equipment and lungs, so airlock cleaning matters.','nasa-moon'),
('moon-11','moon','advanced','Mission decision: Lunar surface temperatures swing hugely between day and night. Which gear matters most?','[{"id":"a","text":"A raincoat"},{"id":"b","text":"A thermally controlled spacesuit"},{"id":"c","text":"Sunglasses only"},{"id":"d","text":"A wind jacket"}]'::jsonb,'b','With almost no atmosphere to moderate heat, suits need active thermal control.','nasa-moon'),
('moon-12','moon','advanced','Mission decision: You want to talk to Earth from the far side of the Moon. What helps most?','[{"id":"a","text":"Shouting louder"},{"id":"b","text":"A relay satellite or relay station"},{"id":"c","text":"Turning off your radio"},{"id":"d","text":"Waiting for the far side to face Earth"}]'::jsonb,'b','The far side never faces Earth, so a relay is needed to pass signals.','nasa-moon'),
('mars-01','mars','beginner','Mars is which planet from the Sun?','[{"id":"a","text":"Second"},{"id":"b","text":"Third"},{"id":"c","text":"Fourth"},{"id":"d","text":"Sixth"}]'::jsonb,'c','Mars is the fourth planet from the Sun.','nasa-mars'),
('mars-02','mars','beginner','What gives Mars its reddish colour?','[{"id":"a","text":"Iron oxide (rust) in its dust"},{"id":"b","text":"Red oceans"},{"id":"c","text":"Lava lakes everywhere"},{"id":"d","text":"Reflected light from Jupiter"}]'::jsonb,'a','Iron-oxide dust colours Mars red.','nasa-mars'),
('mars-03','mars','beginner','How many moons does Mars have?','[{"id":"a","text":"None"},{"id":"b","text":"One"},{"id":"c","text":"Two"},{"id":"d","text":"Seventy"}]'::jsonb,'c','Mars has two small moons: Phobos and Deimos.','nasa-mars'),
('mars-04','mars','beginner','What is the giant volcano on Mars called?','[{"id":"a","text":"Mount Everest"},{"id":"b","text":"Maxwell Montes"},{"id":"c","text":"Mauna Kea"},{"id":"d","text":"Olympus Mons"}]'::jsonb,'d','Olympus Mons is the largest known volcano in the solar system.','nasa-mars'),
('mars-05','mars','intermediate','Mars’ atmosphere is best described as…','[{"id":"a","text":"Thick and oxygen-rich"},{"id":"b","text":"Thin and mostly carbon dioxide"},{"id":"c","text":"Thick sulfuric-acid clouds"},{"id":"d","text":"Absent completely"}]'::jsonb,'b','Mars has a thin atmosphere made mostly of CO₂ — not breathable.','nasa-mars'),
('mars-06','mars','intermediate','About how strong is surface gravity on Mars?','[{"id":"a","text":"About 38% of Earth’s"},{"id":"b","text":"About 1/6 of Earth’s"},{"id":"c","text":"Twice Earth’s"},{"id":"d","text":"The same as Earth’s"}]'::jsonb,'a','Mars gravity is about 0.38 g. (1/6 g is the Moon.)','nasa-mars'),
('mars-07','mars','intermediate','A "sol" is…','[{"id":"a","text":"A Martian year"},{"id":"b","text":"A Martian moon"},{"id":"c","text":"A Martian day of about 24 h 37 min"},{"id":"d","text":"A type of rover"}]'::jsonb,'c','A sol is one Martian day — just a little longer than an Earth day.','nasa-mars'),
('mars-08','mars','intermediate','Compared with Earth, Mars is…','[{"id":"a","text":"Twice as wide"},{"id":"b","text":"About the same size"},{"id":"c","text":"Bigger than Jupiter"},{"id":"d","text":"About half Earth’s diameter"}]'::jsonb,'d','Mars is roughly half Earth’s diameter.','nasa-mars'),
('mars-09','mars','advanced','Mission decision: Why does a Mars habitat need engineered life support?','[{"id":"a","text":"Martian air is too warm"},{"id":"b","text":"Mars air is thin, mostly CO₂, and not breathable"},{"id":"c","text":"Mars has too much oxygen"},{"id":"d","text":"Habitats need it only for decoration"}]'::jsonb,'b','Breathable oxygen is not freely available on Mars; habitats must supply it.','nasa-mars'),
('mars-10','mars','advanced','Mission decision: A dust storm is coming. What is the best action for your solar-powered base?','[{"id":"a","text":"Clean panels later and store power now"},{"id":"b","text":"Turn off all heaters forever"},{"id":"c","text":"Open the airlock to let the dust out"},{"id":"d","text":"Walk into the storm to watch it"}]'::jsonb,'a','Dust reduces sunlight and coats panels, so storing energy and planning cleaning is wise.','nasa-mars'),
('mars-11','mars','advanced','Mission decision: Where would you look for water to support a Mars base?','[{"id":"a","text":"Flowing surface rivers"},{"id":"b","text":"Underground ice and polar ice caps"},{"id":"c","text":"Inside Olympus Mons lava"},{"id":"d","text":"In the CO₂ clouds only"}]'::jsonb,'b','Liquid water is unstable at Mars’ low pressure; water exists mainly as ice.','nasa-mars'),
('mars-12','mars','advanced','Mission decision: Plants in your hydroponic bay need what Mars air cannot provide. What must the habitat control?','[{"id":"a","text":"Nothing — plants grow fine outside"},{"id":"b","text":"Only the colour of the lights"},{"id":"c","text":"Pressure, temperature, water and nutrients"},{"id":"d","text":"The number of moons"}]'::jsonb,'c','Hydroponics needs a controlled environment because the Martian surface is cold and low-pressure.','nasa-mars'),
('venus-01','venus','beginner','Which is the hottest planet in our solar system?','[{"id":"a","text":"Mercury"},{"id":"b","text":"Venus"},{"id":"c","text":"Mars"},{"id":"d","text":"Jupiter"}]'::jsonb,'b','Venus is hotter than Mercury because its thick atmosphere traps heat.','nasa-venus'),
('venus-02','venus','beginner','Venus is which planet from the Sun?','[{"id":"a","text":"Second"},{"id":"b","text":"First"},{"id":"c","text":"Third"},{"id":"d","text":"Fifth"}]'::jsonb,'a','Venus is the second planet from the Sun.','nasa-venus'),
('venus-03','venus','beginner','Venus is about the same size as…','[{"id":"a","text":"The Moon"},{"id":"b","text":"Jupiter"},{"id":"c","text":"Earth"},{"id":"d","text":"The Sun"}]'::jsonb,'c','Venus and Earth are similar in size.','nasa-venus'),
('venus-04','venus','beginner','Venus’ clouds contain…','[{"id":"a","text":"Liquid water rain"},{"id":"b","text":"Sulfuric acid"},{"id":"c","text":"Pure oxygen"},{"id":"d","text":"Ice crystals of nitrogen"}]'::jsonb,'b','Venus has thick clouds of sulfuric acid.','nasa-venus'),
('venus-05','venus','intermediate','Why is Venus hotter than Mercury?','[{"id":"a","text":"It is closer to the Sun"},{"id":"b","text":"It has volcanoes erupting every second"},{"id":"c","text":"Its thick CO₂ atmosphere traps heat (greenhouse effect)"},{"id":"d","text":"It has no atmosphere"}]'::jsonb,'c','A runaway greenhouse effect traps heat, giving surface temperatures around 465 °C.','nasa-venus'),
('venus-06','venus','intermediate','Surface pressure on Venus is about…','[{"id":"a","text":"90 times Earth’s"},{"id":"b","text":"Half of Earth’s"},{"id":"c","text":"Equal to Earth’s"},{"id":"d","text":"Zero"}]'::jsonb,'a','Venus surface pressure is about 90 times Earth’s — like being deep underwater.','nasa-venus'),
('venus-07','venus','intermediate','Which statement about Venus’ spin is true?','[{"id":"a","text":"It spins faster than Earth"},{"id":"b","text":"It does not orbit the Sun"},{"id":"c","text":"Its day is shorter than an hour"},{"id":"d","text":"It spins backwards (retrograde) and very slowly"}]'::jsonb,'d','Venus rotates retrograde and so slowly that its day is longer than its year.','nasa-venus'),
('venus-08','venus','intermediate','Venus’ atmosphere is mostly made of…','[{"id":"a","text":"Nitrogen"},{"id":"b","text":"Carbon dioxide"},{"id":"c","text":"Oxygen"},{"id":"d","text":"Helium"}]'::jsonb,'b','Venus’ thick atmosphere is mostly carbon dioxide.','nasa-venus'),
('venus-09','venus','advanced','Mission decision: Why must your craft carry a heat-shield module before going to Venus?','[{"id":"a","text":"Venus is freezing"},{"id":"b","text":"For decoration"},{"id":"c","text":"Extreme heat and pressure would damage unprotected equipment"},{"id":"d","text":"To block moonlight"}]'::jsonb,'c','Venus’ extreme conditions demand heat and pressure protection.','nasa-venus'),
('venus-10','venus','advanced','Mission decision: Your platform panel shows acid corrosion. What do you do?','[{"id":"a","text":"Repair with acid-resistant panels"},{"id":"b","text":"Ignore it — acid helps"},{"id":"c","text":"Paint it red"},{"id":"d","text":"Open the panel to vent heat inside"}]'::jsonb,'a','Sulfuric-acid clouds corrode materials, so acid-resistant repairs are needed.','nasa-venus'),
('venus-11','venus','advanced','Mission decision: Should a crewed mission try to walk on Venus’ surface?','[{"id":"a","text":"Yes, with a normal spacesuit"},{"id":"b","text":"Yes, at night when it is cool"},{"id":"c","text":"Only on Sundays"},{"id":"d","text":"No — heat and pressure make it deadly; use robots or high-altitude platforms"}]'::jsonb,'d','No current suit could survive Venus’ surface; robots and orbiters study it.','nasa-venus'),
('venus-12','venus','advanced','Mission decision: Can you breathe Venus’ air through a filter mask?','[{"id":"a","text":"Yes, it is mostly oxygen"},{"id":"b","text":"No — it is mostly CO₂ with acid clouds; you need full life support"},{"id":"c","text":"Yes, but only at the poles"},{"id":"d","text":"Yes, after it rains"}]'::jsonb,'b','Breathable oxygen is not freely available on Venus; crews need sealed life support.','nasa-venus'),
('saturn-01','saturn','beginner','Saturn is best known for its…','[{"id":"a","text":"Blue oceans"},{"id":"b","text":"Bright rings"},{"id":"c","text":"Red dust"},{"id":"d","text":"Single volcano"}]'::jsonb,'b','Saturn has the most spectacular ring system in the solar system.','nasa-saturn'),
('saturn-02','saturn','beginner','What type of planet is Saturn?','[{"id":"a","text":"Rocky planet"},{"id":"b","text":"Dwarf planet"},{"id":"c","text":"Gas giant"},{"id":"d","text":"Star"}]'::jsonb,'c','Saturn is a gas giant made mostly of hydrogen and helium.','nasa-saturn'),
('saturn-03','saturn','beginner','What is Saturn’s largest moon?','[{"id":"a","text":"Titan"},{"id":"b","text":"Phobos"},{"id":"c","text":"Europa"},{"id":"d","text":"The Moon"}]'::jsonb,'a','Titan is Saturn’s largest moon and has a thick atmosphere.','nasa-saturn'),
('saturn-04','saturn','beginner','Saturn is which planet from the Sun?','[{"id":"a","text":"Fourth"},{"id":"b","text":"Fifth"},{"id":"c","text":"Seventh"},{"id":"d","text":"Sixth"}]'::jsonb,'d','Saturn is the sixth planet from the Sun.','nasa-saturn'),
('saturn-05','saturn','intermediate','Saturn’s rings are made of…','[{"id":"a","text":"Solid metal hoops"},{"id":"b","text":"Gas only"},{"id":"c","text":"Countless pieces of ice and rock"},{"id":"d","text":"Light reflections with no material"}]'::jsonb,'c','The rings are billions of ice and rock particles orbiting Saturn.','nasa-saturn'),
('saturn-06','saturn','intermediate','Why can’t a spacecraft land on Saturn?','[{"id":"a","text":"It has no solid surface"},{"id":"b","text":"It is too small"},{"id":"c","text":"It is made of ice only"},{"id":"d","text":"Its rings block every path"}]'::jsonb,'a','Saturn is mostly gas and liquid hydrogen/helium with no solid landing surface.','nasa-saturn'),
('saturn-07','saturn','intermediate','Saturn’s average density is…','[{"id":"a","text":"Higher than iron"},{"id":"b","text":"Equal to Earth’s"},{"id":"c","text":"Higher than Earth’s"},{"id":"d","text":"Less than water"}]'::jsonb,'d','Saturn is the least dense planet — on average less dense than water.','nasa-saturn'),
('saturn-08','saturn','intermediate','About how far is Saturn from the Sun on average?','[{"id":"a","text":"1 AU"},{"id":"b","text":"9.5 AU"},{"id":"c","text":"0.5 AU"},{"id":"d","text":"100 AU"}]'::jsonb,'b','Saturn orbits about 9.5 AU (≈1.4 billion km) from the Sun.','nasa-saturn'),
('saturn-09','saturn','advanced','Mission decision: Where should a crewed Saturn base be placed?','[{"id":"a","text":"On Saturn’s solid surface"},{"id":"b","text":"Inside the rings"},{"id":"c","text":"In a protected orbit as a station"},{"id":"d","text":"At Saturn’s core"}]'::jsonb,'c','With no surface to land on, an orbital station is the sensible (fictional) choice.','nasa-saturn'),
('saturn-10','saturn','advanced','Mission decision: Ring particles are drifting near the station. What protects you best?','[{"id":"a","text":"Shielding and keeping a safe distance"},{"id":"b","text":"Flying straight through the thickest ring"},{"id":"c","text":"Turning off all sensors"},{"id":"d","text":"Opening the windows"}]'::jsonb,'a','Even small particles can damage spacecraft; shielding and safe trajectories matter.','nasa-saturn'),
('saturn-11','saturn','advanced','Mission decision: The station power grid is scrambled. What is the smart first step?','[{"id":"a","text":"Unplug everything at random"},{"id":"b","text":"Check which systems need power and route energy carefully"},{"id":"c","text":"Fly closer to Saturn for warmth"},{"id":"d","text":"Ignore it until the lights return"}]'::jsonb,'b','Careful energy routing keeps life-support and essential systems running first.','nasa-saturn'),
('saturn-12','saturn','advanced','Mission decision: Titan has a thick atmosphere. What does that tell you about life there?','[{"id":"a","text":"Life is confirmed on Titan"},{"id":"b","text":"Titan has breathable oxygen"},{"id":"c","text":"Titan is a star"},{"id":"d","text":"An atmosphere alone does not prove life exists"}]'::jsonb,'d','Interesting conditions do not prove life; scientists need evidence.','nasa-saturn'),
('sun-01','sun','beginner','The Sun is a…','[{"id":"a","text":"Planet"},{"id":"b","text":"Star"},{"id":"c","text":"Moon"},{"id":"d","text":"Comet"}]'::jsonb,'b','The Sun is a star — the closest one to Earth.','nasa-sun'),
('sun-02','sun','beginner','What powers the Sun?','[{"id":"a","text":"Burning coal"},{"id":"b","text":"Nuclear fusion in its core"},{"id":"c","text":"Electricity from Earth"},{"id":"d","text":"Reflected starlight"}]'::jsonb,'b','Fusion of hydrogen into helium in the core powers the Sun.','nasa-sun'),
('sun-03','sun','beginner','About how long does sunlight take to reach Earth?','[{"id":"a","text":"8 seconds"},{"id":"b","text":"8 days"},{"id":"c","text":"8 minutes"},{"id":"d","text":"8 years"}]'::jsonb,'c','Sunlight travels about 150 million km in roughly 8 minutes.','nasa-sun'),
('sun-04','sun','beginner','Is it safe to look directly at the Sun?','[{"id":"a","text":"No — use certified solar filters"},{"id":"b","text":"Yes, at noon"},{"id":"c","text":"Yes, with normal sunglasses"},{"id":"d","text":"Yes, through a telescope without filters"}]'::jsonb,'a','Looking at the Sun can cause permanent eye damage without certified filters.','nasa-sun'),
('sun-05','sun','intermediate','Sunspots are…','[{"id":"a","text":"Holes through the Sun"},{"id":"b","text":"Planets crossing the Sun"},{"id":"c","text":"Hotter, brighter patches"},{"id":"d","text":"Cooler, darker regions caused by magnetic activity"}]'::jsonb,'d','Sunspots are cooler regions linked to strong magnetic fields.','nasa-sun'),
('sun-06','sun','intermediate','About how many Earths would fit across the Sun’s diameter?','[{"id":"a","text":"About 109"},{"id":"b","text":"About 10"},{"id":"c","text":"About 2"},{"id":"d","text":"About 1 million"}]'::jsonb,'a','The Sun’s diameter is about 109 times Earth’s.','nasa-sun'),
('sun-07','sun','intermediate','What is 1 AU?','[{"id":"a","text":"One Sun width"},{"id":"b","text":"The average Earth–Sun distance (≈150 million km)"},{"id":"c","text":"The distance to the Moon"},{"id":"d","text":"One light-year"}]'::jsonb,'b','An astronomical unit is the average Earth–Sun distance.','nasa-sun'),
('sun-08','sun','intermediate','The Sun is made mostly of…','[{"id":"a","text":"Rock and iron"},{"id":"b","text":"Water and ice"},{"id":"c","text":"Hydrogen and helium plasma"},{"id":"d","text":"Oxygen and nitrogen"}]'::jsonb,'c','The Sun is hot plasma, mostly hydrogen and helium.','nasa-sun'),
('sun-09','sun','advanced','Mission decision: Can a spacecraft land on the Sun?','[{"id":"a","text":"Yes, on a cool sunspot"},{"id":"b","text":"No — it has no solid surface and is extremely hot"},{"id":"c","text":"Yes, at night"},{"id":"d","text":"Yes, with a heat shield"}]'::jsonb,'b','The Sun is plasma with no landing surface; probes study it from a distance.','nasa-sun'),
('sun-10','sun','advanced','Mission decision: A solar flare alert arrives. What do you do on the observation deck?','[{"id":"a","text":"Go outside to watch"},{"id":"b","text":"Remove your visor"},{"id":"c","text":"Raise radiation shielding and protect instruments"},{"id":"d","text":"Point the telescope without filters"}]'::jsonb,'c','Flares release radiation that can harm crews and electronics.','nasa-sun'),
('sun-11','sun','advanced','Mission decision: Which instrument setup is safest for studying the Sun?','[{"id":"a","text":"A telescope with certified solar filters, viewed remotely"},{"id":"b","text":"Binoculars without filters"},{"id":"c","text":"Looking through a window"},{"id":"d","text":"A mirror pointed at your eyes"}]'::jsonb,'a','Proper filters and remote viewing keep observers safe.','nasa-sun'),
('sun-12','sun','advanced','Mission decision: Space weather could disturb your radio link to Earth. What is the best plan?','[{"id":"a","text":"Never use radio again"},{"id":"b","text":"Turn off life support"},{"id":"c","text":"Fly toward the Sun"},{"id":"d","text":"Store data and transmit when conditions improve"}]'::jsonb,'d','Solar activity can disrupt communication; buffering data is a good strategy.','nasa-sun'),
('asteroid-01','asteroid','beginner','What are asteroids?','[{"id":"a","text":"Rocky leftovers from the solar system’s formation"},{"id":"b","text":"Small stars"},{"id":"c","text":"Human-made satellites"},{"id":"d","text":"Balls of gas"}]'::jsonb,'a','Asteroids are rocky, airless remnants from when planets formed.','nasa-asteroids'),
('asteroid-02','asteroid','beginner','Where do most known asteroids orbit?','[{"id":"a","text":"Inside the Sun"},{"id":"b","text":"Around the Moon only"},{"id":"c","text":"In the main belt between Mars and Jupiter"},{"id":"d","text":"Beyond the Oort Cloud"}]'::jsonb,'c','Most known asteroids are in the main belt between Mars and Jupiter.','nasa-asteroids'),
('asteroid-03','asteroid','beginner','Do asteroids have breathable air?','[{"id":"a","text":"Yes, lots"},{"id":"b","text":"Only big ones"},{"id":"c","text":"Only near Jupiter"},{"id":"d","text":"No — they have no air"}]'::jsonb,'d','Asteroids are airless.','nasa-asteroids'),
('asteroid-04','asteroid','beginner','Asteroids can be as large as…','[{"id":"a","text":"Hundreds of kilometres"},{"id":"b","text":"Only a few centimetres"},{"id":"c","text":"Larger than the Sun"},{"id":"d","text":"Exactly 1 km always"}]'::jsonb,'a','Sizes range from a few metres to hundreds of kilometres.','nasa-asteroids'),
('asteroid-05','asteroid','intermediate','Why do astronauts need tethers on a small asteroid?','[{"id":"a","text":"Its gravity is very weak, so you could drift away"},{"id":"b","text":"Its gravity is crushing"},{"id":"c","text":"It has strong winds"},{"id":"d","text":"It spins backwards"}]'::jsonb,'a','Tiny gravity means a push could send you floating off.','nasa-asteroids'),
('asteroid-06','asteroid','intermediate','A "rubble pile" asteroid is…','[{"id":"a","text":"A solid ball of iron"},{"id":"b","text":"A loose collection of rocks held together by gravity"},{"id":"c","text":"A comet with a tail"},{"id":"d","text":"A moon of Earth"}]'::jsonb,'b','Some asteroids are loosely bound piles of rubble.','nasa-asteroids'),
('asteroid-07','asteroid','intermediate','In films the asteroid belt is crowded. In reality…','[{"id":"a","text":"Asteroids touch each other"},{"id":"b","text":"Ships cannot pass"},{"id":"c","text":"Asteroids are usually very far apart"},{"id":"d","text":"It is a solid ring"}]'::jsonb,'c','The belt is mostly empty space; asteroids are widely spaced.','nasa-asteroids'),
('asteroid-08','asteroid','intermediate','How is an asteroid different from a comet?','[{"id":"a","text":"Asteroids have bigger tails"},{"id":"b","text":"Asteroids are mostly rock/metal; comets are icy and grow tails near the Sun"},{"id":"c","text":"There is no difference"},{"id":"d","text":"Asteroids are stars"}]'::jsonb,'b','Comets contain ice that vaporises near the Sun; asteroids are mostly rocky.','nasa-asteroids'),
('asteroid-09','asteroid','advanced','Mission decision: Why collect asteroid samples?','[{"id":"a","text":"To sell them as jewellery"},{"id":"b","text":"To build rockets on the spot"},{"id":"c","text":"To make the asteroid lighter"},{"id":"d","text":"To learn about the early solar system"}]'::jsonb,'d','Asteroids preserve material from the solar system’s birth.','nasa-asteroids'),
('asteroid-10','asteroid','advanced','Mission decision: The surface is loose rubble. How should you move?','[{"id":"a","text":"Jump as high as possible"},{"id":"b","text":"Move slowly, stay tethered, use gentle thrusters"},{"id":"c","text":"Run fast"},{"id":"d","text":"Remove your boots"}]'::jsonb,'b','Gentle, anchored movement prevents drifting off a low-gravity rubble pile.','nasa-asteroids'),
('asteroid-11','asteroid','advanced','Mission decision: How should samples be stored for return?','[{"id":"a","text":"In an open bag"},{"id":"b","text":"Mixed together"},{"id":"c","text":"In sealed, labelled containers to avoid contamination"},{"id":"d","text":"In your helmet"}]'::jsonb,'c','Sealed containers keep samples clean for scientists.','nasa-asteroids'),
('asteroid-12','asteroid','advanced','Mission decision: KT-7 in this game is…','[{"id":"a","text":"A fictional training asteroid"},{"id":"b","text":"A real asteroid visited by Apollo"},{"id":"c","text":"A moon of Mars"},{"id":"d","text":"A comet"}]'::jsonb,'a','KT-7 is Simulation Fiction, used to practise real asteroid science.','nasa-asteroids'),
('comet-01','comet','beginner','Comets are made mostly of…','[{"id":"a","text":"Ice, dust and rock"},{"id":"b","text":"Burning gas like the Sun"},{"id":"c","text":"Metal only"},{"id":"d","text":"Liquid water oceans"}]'::jsonb,'a','Comets are icy leftovers from the solar system’s formation.','nasa-comets'),
('comet-02','comet','beginner','The solid centre of a comet is called the…','[{"id":"a","text":"Corona"},{"id":"b","text":"Mantle"},{"id":"c","text":"Nucleus"},{"id":"d","text":"Crater"}]'::jsonb,'c','A comet’s solid centre is its nucleus.','nasa-comets'),
('comet-03','comet','beginner','When a comet nears the Sun it forms…','[{"id":"a","text":"A ring system"},{"id":"b","text":"A coma and tails"},{"id":"c","text":"A moon"},{"id":"d","text":"A crater"}]'::jsonb,'b','Heat releases gas and dust, creating a coma and tails.','nasa-comets'),
('comet-04','comet','beginner','A comet’s tails point…','[{"id":"a","text":"Toward the Sun"},{"id":"b","text":"Toward Earth"},{"id":"c","text":"Always downward"},{"id":"d","text":"Away from the Sun"}]'::jsonb,'d','Sunlight and the solar wind push tails away from the Sun.','nasa-comets'),
('comet-05','comet','intermediate','Where are many long-period comets thought to come from?','[{"id":"a","text":"The Oort Cloud"},{"id":"b","text":"The Moon"},{"id":"c","text":"The asteroid belt only"},{"id":"d","text":"Inside the Sun"}]'::jsonb,'a','Long-period comets are thought to come from the inferred Oort Cloud.','nasa-comets'),
('comet-06','comet','intermediate','Why does a comet only grow a tail near the Sun?','[{"id":"a","text":"Comets are scared of the dark"},{"id":"b","text":"The Sun’s heat turns ice into gas that carries dust"},{"id":"c","text":"Planets pull tails out"},{"id":"d","text":"Tails are always there but invisible"}]'::jsonb,'b','Solar heating makes ices vaporise and release dust.','nasa-comets'),
('comet-07','comet','intermediate','Many short-period comets come from…','[{"id":"a","text":"Earth’s oceans"},{"id":"b","text":"Saturn’s rings"},{"id":"c","text":"The Kuiper Belt"},{"id":"d","text":"The Sun"}]'::jsonb,'c','The Kuiper Belt beyond Neptune supplies many short-period comets.','nasa-comets'),
('comet-08','comet','intermediate','Meteor showers happen when Earth passes through…','[{"id":"a","text":"A planet’s ring"},{"id":"b","text":"The Moon’s shadow"},{"id":"c","text":"Solar wind only"},{"id":"d","text":"Dust left behind by comets"}]'::jsonb,'d','Comet dust burning up in our air creates meteor showers.','nasa-comets'),
('comet-09','comet','advanced','Mission decision: Dust jets are erupting. How should you approach?','[{"id":"a","text":"Fly into the jet for a closer look"},{"id":"b","text":"Keep a safe flyby distance behind a dust shield"},{"id":"c","text":"Land on the jet"},{"id":"d","text":"Turn off the shield to save power"}]'::jsonb,'b','Dust particles can damage spacecraft, so shielded flybys are safer.','nasa-comets'),
('comet-10','comet','advanced','Mission decision: Your scanner detects water ice. Why is that exciting?','[{"id":"a","text":"It proves aliens live there"},{"id":"b","text":"Ice is rare everywhere in space"},{"id":"c","text":"It helps us learn what the early solar system was made of"},{"id":"d","text":"It means the comet is a planet"}]'::jsonb,'c','Comet ices preserve ancient material; ice alone is not evidence of life.','nasa-comets'),
('comet-11','comet','advanced','Mission decision: Which way should you point your camera to film the tail?','[{"id":"a","text":"Away from the Sun, behind the comet"},{"id":"b","text":"Directly at the Sun"},{"id":"c","text":"At Earth"},{"id":"d","text":"At the nucleus only"}]'::jsonb,'a','Tails stream away from the Sun.','nasa-comets'),
('comet-12','comet','advanced','Mission decision: Lumen-K in this game is…','[{"id":"a","text":"A famous real comet"},{"id":"b","text":"A planet"},{"id":"c","text":"A star"},{"id":"d","text":"A fictional comet used for training"}]'::jsonb,'d','Lumen-K is Simulation Fiction based on real comet science.','nasa-comets'),
('exoplanet-01','exoplanet','beginner','An exoplanet is…','[{"id":"a","text":"A planet outside our solar system"},{"id":"b","text":"A planet that exploded"},{"id":"c","text":"A moon of Mars"},{"id":"d","text":"A human-made planet"}]'::jsonb,'a','Exoplanets orbit stars other than the Sun.','nasa-exoplanets'),
('exoplanet-02','exoplanet','beginner','About how many exoplanets have been confirmed?','[{"id":"a","text":"Exactly eight"},{"id":"b","text":"None yet"},{"id":"c","text":"Thousands"},{"id":"d","text":"Only one"}]'::jsonb,'c','Thousands of exoplanets have been confirmed.','nasa-exoplanets'),
('exoplanet-03','exoplanet','beginner','Which tool do scientists mainly use to find exoplanets?','[{"id":"a","text":"Microscopes"},{"id":"b","text":"Telescopes"},{"id":"c","text":"Submarines"},{"id":"d","text":"Weather balloons"}]'::jsonb,'b','Space and ground telescopes detect exoplanets.','nasa-exoplanets'),
('exoplanet-04','exoplanet','beginner','Real exoplanets are usually…','[{"id":"a","text":"Next door to Earth"},{"id":"b","text":"Inside our Moon"},{"id":"c","text":"In our asteroid belt"},{"id":"d","text":"Light-years away"}]'::jsonb,'d','Even the nearest stars are light-years away.','nasa-exoplanets'),
('exoplanet-05','exoplanet','intermediate','The transit method spots a planet by…','[{"id":"a","text":"A small dip in a star’s brightness"},{"id":"b","text":"Hearing it"},{"id":"c","text":"Seeing its cities"},{"id":"d","text":"Its smell"}]'::jsonb,'a','When a planet passes in front of its star, the star dims slightly.','nasa-exoplanets'),
('exoplanet-06','exoplanet','intermediate','The habitable zone is where…','[{"id":"a","text":"Life definitely exists"},{"id":"b","text":"Liquid water could exist on a planet’s surface"},{"id":"c","text":"Planets are always frozen"},{"id":"d","text":"Stars are born"}]'::jsonb,'b','It is the distance range where liquid water could be possible.','nasa-exoplanets'),
('exoplanet-07','exoplanet','intermediate','How can telescopes learn what gases are in an exoplanet’s atmosphere?','[{"id":"a","text":"By landing probes"},{"id":"b","text":"By listening for sound"},{"id":"c","text":"By analysing starlight that passes through it (spectroscopy)"},{"id":"d","text":"By weighing the star"}]'::jsonb,'c','Spectroscopy reveals gases by how they absorb light.','nasa-exoplanets'),
('exoplanet-08','exoplanet','intermediate','A planet in the habitable zone…','[{"id":"a","text":"Is proven to have life"},{"id":"b","text":"Has oceans for sure"},{"id":"c","text":"Is always Earth-sized"},{"id":"d","text":"Might have conditions for liquid water, but life is unknown"}]'::jsonb,'d','Potential habitability does not prove life exists.','nasa-exoplanets'),
('exoplanet-09','exoplanet','advanced','Mission decision: Your data shows one interesting gas. What should your report say?','[{"id":"a","text":"\"Aliens confirmed!\""},{"id":"b","text":"\"An interesting signal that needs more evidence and checking\""},{"id":"c","text":"\"Nothing is there\""},{"id":"d","text":"\"The planet is Earth\""}]'::jsonb,'b','Scientists need multiple lines of evidence before big claims.','nasa-exoplanets'),
('exoplanet-10','exoplanet','advanced','Mission decision: Why repeat a transit observation several times?','[{"id":"a","text":"To confirm the dip repeats regularly with the planet’s orbit"},{"id":"b","text":"To make the star brighter"},{"id":"c","text":"To scare the planet"},{"id":"d","text":"It is never needed"}]'::jsonb,'a','Repeating transits confirm a real orbiting planet.','nasa-exoplanets'),
('exoplanet-11','exoplanet','advanced','Mission decision: Aurelia b in this game is…','[{"id":"a","text":"A confirmed habitable world"},{"id":"b","text":"Our Moon"},{"id":"c","text":"A fictional simulated exoplanet"},{"id":"d","text":"A star"}]'::jsonb,'c','Aurelia b is Simulation Fiction for practising real methods.','nasa-exoplanets'),
('exoplanet-12','exoplanet','advanced','Mission decision: Cosmic rays add noise to your sensor. Best action?','[{"id":"a","text":"Delete all data"},{"id":"b","text":"Turn the telescope toward Earth"},{"id":"c","text":"Report the planet as fake"},{"id":"d","text":"Filter the noise and compare several measurements"}]'::jsonb,'d','Careful data processing and repeated measurements reduce errors.','nasa-exoplanets'),
('satellite-01','satellite','beginner','An artificial satellite is…','[{"id":"a","text":"A natural moon"},{"id":"b","text":"A human-made machine in orbit"},{"id":"c","text":"A small star"},{"id":"d","text":"A comet"}]'::jsonb,'b','Artificial satellites are built and launched by people.','nasa-satellites'),
('satellite-02','satellite','beginner','Which is a common use of satellites?','[{"id":"a","text":"Weather forecasting"},{"id":"b","text":"Growing crops in space"},{"id":"c","text":"Making volcanoes"},{"id":"d","text":"Cleaning oceans directly"}]'::jsonb,'a','Satellites help with weather, communication, navigation and science.','nasa-satellites'),
('satellite-03','satellite','beginner','Many satellites get power from…','[{"id":"a","text":"Petrol engines"},{"id":"b","text":"Wind turbines"},{"id":"c","text":"Solar panels"},{"id":"d","text":"Batteries charged on Earth only"}]'::jsonb,'c','Solar panels turn sunlight into electricity.','nasa-satellites'),
('satellite-04','satellite','beginner','The Moon is a natural satellite. A GPS satellite is…','[{"id":"a","text":"Also natural"},{"id":"b","text":"A planet"},{"id":"c","text":"A star"},{"id":"d","text":"Artificial"}]'::jsonb,'d','GPS satellites are human-made, so they are artificial.','nasa-satellites'),
('satellite-05','satellite','intermediate','Why doesn’t a satellite fall to Earth?','[{"id":"a","text":"There is no gravity in space"},{"id":"b","text":"It moves sideways so fast it keeps falling around Earth"},{"id":"c","text":"It is held by cables"},{"id":"d","text":"It floats on air"}]'::jsonb,'b','Orbit is continuous free fall combined with high sideways speed.','nasa-satellites'),
('satellite-06','satellite','intermediate','Space debris is dangerous because…','[{"id":"a","text":"It is radioactive"},{"id":"b","text":"It is magnetic"},{"id":"c","text":"Even tiny pieces move extremely fast"},{"id":"d","text":"It is sticky"}]'::jsonb,'c','High speed means even small fragments can damage spacecraft.','nasa-satellites'),
('satellite-07','satellite','intermediate','GPS navigation works by…','[{"id":"a","text":"Satellites sending timing signals to receivers"},{"id":"b","text":"Satellites taking selfies"},{"id":"c","text":"Reading road signs"},{"id":"d","text":"Bouncing signals off the Moon"}]'::jsonb,'a','GPS receivers use timing signals from several satellites.','nasa-satellites'),
('satellite-08','satellite','intermediate','Which statement is true?','[{"id":"a","text":"All satellites are natural"},{"id":"b","text":"Satellites only orbit Earth"},{"id":"c","text":"Satellites cannot carry cameras"},{"id":"d","text":"Some artificial satellites orbit other worlds such as Mars"}]'::jsonb,'d','Orbiters around Mars and other worlds are artificial satellites too.','nasa-satellites'),
('satellite-09','satellite','advanced','Mission decision: You are repairing a panel outside. What keeps you safe?','[{"id":"a","text":"A tether connected to the satellite"},{"id":"b","text":"Holding your breath"},{"id":"c","text":"Removing your gloves for grip"},{"id":"d","text":"Floating freely"}]'::jsonb,'a','Tethers stop astronauts drifting away during spacewalks.','nasa-satellites'),
('satellite-10','satellite','advanced','Mission decision: A piece of debris is on a collision course. What should the satellite do?','[{"id":"a","text":"Turn off power"},{"id":"b","text":"Do an avoidance manoeuvre with its thrusters"},{"id":"c","text":"Open its solar panels wider"},{"id":"d","text":"Nothing"}]'::jsonb,'b','Operators move satellites to avoid tracked debris.','nasa-satellites'),
('satellite-11','satellite','advanced','Mission decision: The satellite enters Earth’s shadow. What happens to its solar power?','[{"id":"a","text":"It increases"},{"id":"b","text":"It stays the same"},{"id":"c","text":"It drops, so batteries must supply power"},{"id":"d","text":"It turns into wind power"}]'::jsonb,'c','In shadow, solar panels get no sunlight; batteries take over.','nasa-satellites'),
('satellite-12','satellite','advanced','Mission decision: Relay-9 in this game is…','[{"id":"a","text":"A real NASA satellite"},{"id":"b","text":"A moon of Saturn"},{"id":"c","text":"A star"},{"id":"d","text":"A fictional satellite for training"}]'::jsonb,'d','Relay-9 is Simulation Fiction based on real satellite engineering.','nasa-satellites'),
('station-01','station','beginner','A space station is…','[{"id":"a","text":"A home and laboratory in orbit"},{"id":"b","text":"A rocket launch pad"},{"id":"c","text":"A planet"},{"id":"d","text":"A star"}]'::jsonb,'a','Space stations let crews live and work in orbit.','nasa-iss'),
('station-02','station','beginner','About how high does the ISS orbit?','[{"id":"a","text":"40 km"},{"id":"b","text":"4,000 km"},{"id":"c","text":"400 km"},{"id":"d","text":"40,000 km"}]'::jsonb,'c','The ISS orbits roughly 400 km above Earth.','nasa-iss'),
('station-03','station','beginner','About how long does the ISS take to orbit Earth once?','[{"id":"a","text":"One year"},{"id":"b","text":"90 minutes"},{"id":"c","text":"One day"},{"id":"d","text":"One week"}]'::jsonb,'b','It circles Earth about every 90 minutes.','nasa-iss'),
('station-04','station','beginner','Who built the International Space Station?','[{"id":"a","text":"One company"},{"id":"b","text":"One student team"},{"id":"c","text":"Nobody — it formed naturally"},{"id":"d","text":"Several space agencies working together"}]'::jsonb,'d','The ISS is a partnership of several space agencies.','nasa-iss'),
('station-05','station','intermediate','Why do astronauts float on the ISS?','[{"id":"a","text":"There is no gravity there"},{"id":"b","text":"They are in continuous free fall around Earth"},{"id":"c","text":"The station spins backwards"},{"id":"d","text":"They wear magnetic boots"}]'::jsonb,'b','Gravity is still strong at 400 km; crews float because they are falling around Earth.','nasa-iss'),
('station-06','station','intermediate','What does station life support do?','[{"id":"a","text":"Supplies oxygen, removes CO₂ and recycles water"},{"id":"b","text":"Makes gravity"},{"id":"c","text":"Shoots lasers"},{"id":"d","text":"Steers the Moon"}]'::jsonb,'a','Life support keeps air and water safe for the crew.','nasa-iss'),
('station-07','station','intermediate','Why must carbon dioxide be removed from station air?','[{"id":"a","text":"It makes the air too cold"},{"id":"b","text":"It is too heavy"},{"id":"c","text":"Too much CO₂ is harmful for the crew"},{"id":"d","text":"It glows"}]'::jsonb,'c','CO₂ builds up from breathing and must be scrubbed.','nasa-iss'),
('station-08','station','intermediate','ISS crews see many sunrises each day because…','[{"id":"a","text":"The Sun moves fast"},{"id":"b","text":"They have special windows"},{"id":"c","text":"Earth spins faster in space"},{"id":"d","text":"They orbit Earth about every 90 minutes"}]'::jsonb,'d','Fast orbits mean about 16 sunrises a day.','nasa-iss'),
('station-09','station','advanced','Mission decision: Oxygen circulation has stopped. What is your first priority?','[{"id":"a","text":"Restore oxygen flow and check CO₂ levels"},{"id":"b","text":"Paint the walls"},{"id":"c","text":"Take photos"},{"id":"d","text":"Open a hatch to space"}]'::jsonb,'a','Crew safety depends on breathable air first.','nasa-iss'),
('station-10','station','advanced','Mission decision: A small leak alarm sounds. What should you do?','[{"id":"a","text":"Ignore it"},{"id":"b","text":"Locate and patch the leak, isolating the module if needed"},{"id":"c","text":"Open all hatches to space"},{"id":"d","text":"Turn off the alarm only"}]'::jsonb,'b','Finding and sealing leaks protects the station atmosphere.','nasa-iss'),
('station-11','station','advanced','Mission decision: Why recycle water on a station?','[{"id":"a","text":"Water is free in space"},{"id":"b","text":"Recycled water tastes better"},{"id":"c","text":"Resupply is limited and expensive, so reuse saves resources"},{"id":"d","text":"Rules require it for fun"}]'::jsonb,'c','Recycling reduces how much must be launched from Earth.','nasa-iss'),
('station-12','station','advanced','Mission decision: Horizon Research Station in this game is…','[{"id":"a","text":"The real ISS"},{"id":"b","text":"A moon"},{"id":"c","text":"A planet"},{"id":"d","text":"A fictional station inspired by real ones"}]'::jsonb,'d','It is Simulation Fiction based on real station science.','nasa-iss')
